let notificationState={slots:[],events:[],read:{},delivered:{}};
try{const saved=JSON.parse(localStorage.getItem('homework-notifications-v1'));if(saved?.slots&&saved.events&&saved.read&&saved.delivered)notificationState=saved}catch{}
function persistNotifications(){try{localStorage.setItem('homework-notifications-v1',JSON.stringify(notificationState));return true}catch{document.getElementById('schoolNotificationStatus').textContent='לא ניתן לשמור התראות בדפדפן הזה.';return false}}
function notificationViewer(){return role==='teacher'?'teacher:'+school.teacherId:role+':'+activeStudentId()}
function slotDue(slot,now=new Date()){if(slot.weekday!==now.getDay())return false;const end=new Date(now);const [hours,minutes]=slot.endTime.split(':').map(Number);end.setHours(hours,minutes,0,0);return now>=end}
function lessonIsUpdated(slot,now=new Date()){return records.some(r=>r.classId===slot.classId&&r.subject===slot.subject&&r.day===key(now))}
function eventVisible(event){return event.classId===activeClassId()&&event.roles.includes(role)}
function currentNotifications(now=new Date()){
 const policy=typeof notificationPolicy==='function'?notificationPolicy(activeSchoolId()):{lesson_end_enabled:true,parent_updates_enabled:true,student_updates_enabled:true};const enabledUpdates=role==='parent'?policy.parent_updates_enabled:role==='child'?policy.student_updates_enabled:true;const entries=notificationState.events.filter(e=>enabledUpdates&&eventVisible(e)).map(e=>({...e,type:'update'}));
 for(const slot of notificationState.slots){if(!policy.lesson_end_enabled||slot.classId!==activeClassId()||!slotDue(slot,now)||lessonIsUpdated(slot,now))continue;if(role==='teacher'&&slot.teacherId!==school.teacherId)continue;if(role!=='teacher'&&!activeStudentId())continue;entries.push({id:'end:'+slot.id+':'+key(now),type:'lesson-end',slot,title:role==='teacher'?'השיעור הסתיים — הגיע הזמן לעדכן':'השיעור הסתיים — ממתינים לעדכון',body:slot.subject+' · '+slot.endTime+(role==='teacher'?' · הוסיפו סיכום, שיעורי בית או אישור שאין שיעורים.':' · כשהמורה יפרסם, העדכון יופיע כאן.'),createdAt:key(now)+'T'+slot.endTime})}
 return entries.sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));
}
function emitLessonUpdate(r){notificationState.events.push({id:crypto.randomUUID(),classId:r.classId,roles:['child','parent'],title:'עדכון חדש מהמורה',body:r.subject+' · '+r.teacher+' · '+(r.kind==='none'?'אין שיעורי בית היום':'נוספו או עודכנו שיעורי הבית')+(r.lesson?' · כולל סיכום שיעור':''),createdAt:r.updatedAt});notificationState.events=notificationState.events.slice(-200);persistNotifications()}
document.getElementById('addLessonReminder').onclick=async()=>{if(role!=='teacher'||!teacherHasClass())return;const endTime=document.getElementById('lessonEndTime').value;if(!/^\d{2}:\d{2}$/.test(endTime))return;const slot={id:crypto.randomUUID(),classId:activeClassId(),teacherId:school.teacherId,subject:document.getElementById('reminderSubject').value,weekday:Number(document.getElementById('reminderWeekday').value),endTime};const duplicate=notificationState.slots.some(s=>s.classId===slot.classId&&s.teacherId===slot.teacherId&&s.subject===slot.subject&&s.weekday===slot.weekday&&s.endTime===slot.endTime);if(!duplicate){if(cloud.ready){try{await cloudSlot(slot)}catch(e){cloudMessage('שמירת התזכורת נכשלה: '+e.message);return}}notificationState.slots.push(slot);persistNotifications()}renderSchoolNotifications()};
document.getElementById('enableSchoolNotifications').onclick=async()=>{const status=document.getElementById('schoolNotificationStatus');if(!('Notification' in window)){status.textContent='התראות הדפדפן אינן נתמכות כאן. אפשר לצפות במרכז ההתראות.';return}try{const permission=await Notification.requestPermission();status.textContent=permission==='granted'?'✓ התראות דפדפן הופעלו כשהאפליקציה פתוחה.':'לא אושרו התראות. הן עדיין יופיעו במרכז ההתראות.';renderSchoolNotifications()}catch{status.textContent='לא ניתן להפעיל התראות דפדפן. מרכז ההתראות זמין.'}};
function renderSchoolNotifications(){
 const list=document.getElementById('schoolNotificationList'),viewer=notificationViewer(),entries=currentNotifications();list.replaceChildren();const unread=entries.filter(e=>!notificationState.read[viewer]?.includes(e.id));document.getElementById('notificationHeading').textContent='🔔 מרכז התראות'+(unread.length?' · '+unread.length+' חדשות':'');if(!entries.length)list.append(el('p','אין התראות חדשות לכיתה ולמשתמש הנבחר.'));
 for(const entry of entries.slice(0,30)){const row=el('div',null,'notice');row.append(el('b',entry.title),el('p',entry.body));if(!notificationState.read[viewer]?.includes(entry.id)){const read=el('button','קראתי','secondary');read.type='button';read.onclick=()=>{notificationState.read[viewer]=[...new Set([...(notificationState.read[viewer]||[]),entry.id])].slice(-300);persistNotifications();renderSchoolNotifications()};row.append(read)}else row.append(el('span','✓ נקרא','meta'));if(entry.type==='lesson-end'&&role==='teacher'){const update=el('button','עדכון השיעור','button');update.type='button';update.onclick=()=>{selected=new Date().getDay();document.getElementById('add').click();form.elements.subject.value=entry.slot.subject};row.append(update)}list.append(row);
 if('Notification' in window&&Notification.permission==='granted'&&!notificationState.delivered[viewer]?.includes(entry.id)&&!notificationState.read[viewer]?.includes(entry.id)){try{new Notification(entry.title,{body:entry.body,tag:viewer+':'+entry.id});notificationState.delivered[viewer]=[...(notificationState.delivered[viewer]||[]),entry.id].slice(-300);persistNotifications()}catch{}}
 }
 const slots=document.getElementById('lessonReminderList');slots.replaceChildren();for(const slot of notificationState.slots.filter(s=>s.classId===activeClassId())){const row=el('div',null,'side-row');row.append(el('span',['ראשון','שני','שלישי','רביעי','חמישי'][slot.weekday]+' · '+slot.subject+' · '+slot.endTime+' · '+(school.teachers.find(t=>t.id===slot.teacherId)?.name||'')));if(role==='teacher'&&slot.teacherId===school.teacherId){const remove=el('button','הסרה','secondary');remove.type='button';remove.onclick=async()=>{if(cloud.ready){try{await cloudSlot(slot,true)}catch(e){cloudMessage(e.message);return}}notificationState.slots=notificationState.slots.filter(s=>s.id!==slot.id);persistNotifications();renderSchoolNotifications()};row.append(remove)}slots.append(row)}
}
setInterval(renderSchoolNotifications,30000);renderSchoolNotifications();
